"""Deterministic metrics and escaped local read-only HTML reports."""
from collections import Counter


def render_report(records, label="Локальный архив", coverage="Только сохранённые письма; полнота серверных ящиков не подтверждена.", proposals=None):
    from html import escape
    def esc(value):
        return escape(str(value if value is not None else ""), quote=True)
    metrics = summarize(records)
    titles = {"university":"Университет", "jobs":"Работа", "finance":"Финансы", "confirmations":"Подтверждения", "housing":"Жильё / ведомства", "security":"Безопасность", "other":"Прочее"}
    cards = "".join(f'<div class="card"><span>{title}</span><strong>{metrics[key]}</strong></div>' for key,title in [("messages","Писем в архиве"),("accounts","Источников в данных"),("documents","Вложений"),("actions","Требуют действия"),("review","Требуют проверки")])
    filters = '<button data-filter="all" class="active">Все письма</button>' + "".join(f'<button data-filter="{esc(k)}">{esc(titles.get(k,k))} <small>{v}</small></button>' for k,v in metrics["topics"].items())
    rows = []
    for r in records:
        evidence = "".join(f'<li><code>{esc(e.get("source_id"))}</code> — {esc(e.get("quote"))}</li>' for e in r.get("evidence", []))
        attachments = "".join(f'<li>{esc(a.get("original_name",a.get("filename",a.get("name","Вложение"))))} · {esc(a.get("extraction_status","unknown"))}</li>' for a in r.get("attachments", []))
        state = "Действие + проверка" if r.get("action_required") else "Проверить" if r.get("needs_review") else "Архив / без действия"
        details = f'<details><summary>Источник и документы</summary><p class="path">{esc(r.get("original_path"))}</p><ul>{evidence}</ul><ul>{attachments}</ul></details>'
        rows.append(f'<tr data-topic="{esc(r.get("topic","other"))}"><td><span class="account">{esc(r.get("account_id"))}</span><div class="dim">{esc(r.get("date",""))}</div></td><td><strong>{esc(r.get("subject","Без темы"))}</strong><div class="dim">{esc(r.get("sender",""))}</div>{details}</td><td>{esc(titles.get(r.get("topic"),r.get("topic","Прочее")))}<div class="dim">{esc(r.get("subtype","unknown"))}</div></td><td><span class="state">{state}</span></td></tr>')
    proposal_rows = "".join(f'<li><strong>{esc(p.get("message_key"))}</strong> · {esc(p.get("subtype"))}<br>{esc(p.get("date_candidate"))}<br><span class="dim">Предложение модели, не подтверждённый факт.</span></li>' for p in (proposals or []))
    return """<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mail Organizer — локальный отчёт</title><style>
:root{color-scheme:dark;--bg:#11151d;--panel:#1a202c;--line:#313b4c;--text:#e8edf5;--dim:#a6b1c4;--accent:#82d7c9}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,Segoe UI,sans-serif}main{max-width:1400px;margin:auto;padding:34px 32px}header{display:flex;justify-content:space-between;align-items:start;gap:24px}h1{font-size:32px;letter-spacing:-1px;margin:4px 0 6px}h2{font-size:18px;margin:0 0 12px}.eyebrow{font-size:11px;letter-spacing:2px;color:var(--accent);text-transform:uppercase}.dim{font-size:12px;color:var(--dim);overflow-wrap:anywhere}.tag{border:1px solid var(--line);padding:7px 12px;border-radius:24px;font-size:12px;white-space:nowrap}.notice{border-left:3px solid var(--accent);padding:12px 16px;background:var(--panel);margin:22px 0;color:var(--dim)}.metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:22px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:18px}.card span{font-size:12px;color:var(--dim)}.card strong{display:block;font-size:34px;line-height:1.5}.toolbar{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}button,input{font:inherit;border:1px solid var(--line);border-radius:8px;padding:8px 12px;background:var(--panel);color:var(--text)}button{cursor:pointer}button.active{border-color:var(--accent);color:var(--accent)}input{min-width:250px;margin-left:auto}small{color:var(--dim)}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px}table{border-collapse:collapse;width:100%;min-width:760px}th{font-size:11px;text-transform:uppercase;letter-spacing:1px;text-align:left;color:var(--dim);background:var(--panel)}td,th{padding:16px;border-bottom:1px solid var(--line);vertical-align:top}tr:last-child td{border-bottom:0}td:nth-child(2){width:48%}.account{font-size:12px;color:var(--accent)}.state{display:inline-block;font-size:11px;border:1px solid var(--line);border-radius:5px;padding:4px 7px}details{margin-top:10px;color:var(--dim);font-size:12px}summary{cursor:pointer}.path{overflow-wrap:anywhere}ul{padding-left:20px}footer{margin-top:24px;color:var(--dim);font-size:12px}.calendar{margin-top:22px;border:1px solid var(--line);border-radius:12px;padding:20px;background:var(--panel)}[hidden]{display:none!important}@media(max-width:800px){main{padding:20px 14px}.metrics{grid-template-columns:repeat(2,1fr)}header{display:block}input{margin-left:0;width:100%}.tag{display:inline-block;margin-top:12px}}
</style></head><body><main>""" + f'<header><div><div class="eyebrow">Mail Organizer / read-only</div><h1>Почта, документы и действия</h1><div class="dim">{esc(label)}</div></div><div class="tag">Без отправки и перемещения писем</div></header><div class="notice">Охват: {esc(coverage)}</div><section class="metrics">{cards}</section><div class="toolbar">{filters}<input id="search" aria-label="Поиск писем" placeholder="Поиск по теме, источнику, статусу"></div><div class="table-wrap"><table><thead><tr><th>Источник</th><th>Письмо / документы</th><th>Категория</th><th>Следующий шаг</th></tr></thead><tbody>{"".join(rows)}</tbody></table></div><section class="calendar"><h2>Календарь не изменяется</h2><p class="dim">Подтверждения сохраняются в архив. Возможные встречи и сроки остаются на проверке. В этой версии отсутствует запись в календарь.</p><ul>{proposal_rows}</ul></section><footer>Показатели рассчитаны программно по сохранённым записям. Модельные предложения не заменяют исходные письма и не выполняют действия.</footer>' + """</main><script>
let selected='all';const buttons=[...document.querySelectorAll('[data-filter]')];const search=document.querySelector('#search');function filter(){const q=search.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(r=>{r.hidden=(selected!=='all'&&r.dataset.topic!==selected)||!r.textContent.toLowerCase().includes(q);});}buttons.forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.filter;buttons.forEach(x=>x.classList.toggle('active',x===b));filter();}));search.addEventListener('input',filter);
</script></body></html>"""



def summarize(records):
    return {"messages": len(records), "accounts": len({r["account_id"] for r in records}),
            "documents": sum(len(r.get("attachments", [])) for r in records),
            "actions": sum(bool(r.get("action_required")) for r in records),
            "review": sum(bool(r.get("needs_review")) for r in records),
            "topics": dict(sorted(Counter(r.get("topic", "other") for r in records).items()))}
